SELECT CAST(ct.clean_task_id AS CHAR) AS taskId, p.poi_name AS poiName, rc.name AS roomCategoryName, r.room_name AS roomName, CAST(ct.clean_staff_id AS CHAR) AS cleanerId, cs.name AS cleanerName, ct.task_type AS taskType, ct.task_status AS taskStatus, COALESCE(ct.remark, '') AS remark, ct.deadline_at AS deadlineAt FROM clean_task ct JOIN pms_poi p ON p.poi_id = ct.poi_id AND p.camp_id = ct.camp_id AND p.status = 1 AND p.is_deleted = 0 JOIN room r ON r.room_id = ct.room_id AND r.camp_id = ct.camp_id AND r.status = 1 AND r.is_deleted = 0 JOIN room_category rc ON rc.room_category_id = ct.room_category_id AND rc.camp_id = ct.camp_id AND rc.status = 1 AND rc.is_deleted = 0 LEFT JOIN clean_staff cs ON cs.clean_staff_id = ct.clean_staff_id AND cs.camp_id = ct.camp_id AND cs.is_deleted = 0 WHERE ct.camp_id = #{campId}
AND ct.poi_id = #{poiId}
AND ct.room_id = #{roomId}
AND ct.clean_staff_id IN
#{cleanerId}
AND DATE(ct.deadline_at) = #{cleanDate}
ORDER BY ct.deadline_at DESC, ct.clean_task_id DESC

SELECT CAST(ct.clean_task_id AS CHAR) AS taskId, p.poi_name AS poiName, rc.name AS roomCategoryName, r.room_name AS roomName, CAST(ct.clean_staff_id AS CHAR) AS cleanerId, cs.name AS cleanerName, ct.task_type AS taskType, ct.task_status AS taskStatus, COALESCE(ct.remark, '') AS remark, ct.deadline_at AS deadlineAt FROM clean_task ct JOIN pms_poi p ON p.poi_id = ct.poi_id AND p.camp_id = ct.camp_id AND p.status = 1 AND p.is_deleted = 0 JOIN room r ON r.room_id = ct.room_id AND r.camp_id = ct.camp_id AND r.status = 1 AND r.is_deleted = 0 JOIN room_category rc ON rc.room_category_id = ct.room_category_id AND rc.camp_id = ct.camp_id AND rc.status = 1 AND rc.is_deleted = 0 LEFT JOIN clean_staff cs ON cs.clean_staff_id = ct.clean_staff_id AND cs.camp_id = ct.camp_id AND cs.is_deleted = 0 WHERE ct.camp_id = #{campId}
AND ct.poi_id = #{poiId}
AND ct.room_id IN
#{roomId}
AND ct.clean_staff_id IN
#{cleanerId}
AND ct.deadline_at >= #{startTime}
AND ct.deadline_at <= #{endTime}
ORDER BY ct.deadline_at ASC, ct.clean_task_id ASC

SELECT r.room_id AS roomId, r.poi_id AS poiId, r.room_category_id AS roomCategoryId FROM room r JOIN pms_poi p ON p.poi_id = r.poi_id AND p.camp_id = r.camp_id AND p.status = 1 AND p.is_deleted = 0 JOIN room_category rc ON rc.room_category_id = r.room_category_id AND rc.camp_id = r.camp_id AND rc.status = 1 AND rc.is_deleted = 0 WHERE r.camp_id = #{campId} AND r.room_id = #{roomId} AND r.status = 1 AND r.is_deleted = 0
AND r.poi_id = #{poiId}
LIMIT 1

SELECT COUNT(*)
FROM clean_staff cs
WHERE cs.camp_id = #{campId}
  AND cs.clean_staff_id = #{cleanStaffId}
  AND cs.status = 1
  AND cs.is_deleted = 0

SELECT CAST(ct.clean_task_id AS CHAR)
FROM clean_task ct
WHERE ct.camp_id = #{campId}
  AND ct.clean_task_id IN

      #{taskId}

ORDER BY ct.clean_task_id ASC
